# Aetherize (FDN): "Return all attacking creatures to their owner's hand."
# MOVE_ZONE to Zone(HAND, OWNER) (Unsummon's bounce) over an ALL selector (QUnbounded: every one,
# no choice) of attacking creatures (IS_ATTACKING, Warded Battlements' filter), any controller.
abilities = [
    SpellAbility(
        kind=SpellKind.INSTANT,
        effect=A(Verb.MOVE_ZONE, {
            'cards': Selector(
                count=QUnbounded(),
                mode=SelectorMode.ALL,
                filter=FAnd(
                    children=(
                        FAtom(pred=FAtomPred.IS_ATTACKING),
                        FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                    ),
                ),
                zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
            ),
            'destination': Zone(kind=ZoneKind.HAND, controller=ControllerRef.OWNER),
        }),
    ),
]
